package com.logatron.investigation.persistence;
import com.logatron.investigation.domain.InvestigationModels.*;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.Instant;import java.util.*;
@Entity @Table(name="investigation") public class InvestigationEntity {
 @Id private UUID id;@Column(name="owner_user_id",nullable=false)private UUID ownerUserId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="environment_id")private UUID environmentId;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="from_time",nullable=false)private Instant fromTime;@Column(name="to_time",nullable=false)private Instant toTime;@Column(name="query_kind",nullable=false,length=40)private String queryKind;@Column(name="query_digest",nullable=false,length=64)private String queryDigest;@Column(nullable=false,length=30)private String status;@JdbcTypeCode(SqlTypes.JSON)@Column(name="evidence_references",nullable=false,columnDefinition="jsonb")private List<String> evidenceReferences;@JdbcTypeCode(SqlTypes.JSON)@Column(name="quality_metadata",nullable=false,columnDefinition="jsonb")private Map<String,String> qualityMetadata;@Column(name="ai_provider",length=80)private String aiProvider;@Column(name="ai_model",length=120)private String aiModel;@Column(name="ai_outcome",length=30)private String aiOutcome;@Column(name="ai_latency_ms")private Long aiLatencyMs;
 protected InvestigationEntity(){}public InvestigationEntity(UUID id,UUID ownerUserId,InvestigationQuery q,String digest,DeterministicResult result,AiResult ai){this.id=id;this.ownerUserId=ownerUserId;projectId=q.projectId();environmentId=q.environmentId();createdAt=Instant.now();fromTime=q.from();toTime=q.to();queryKind=q.identifierType().name();queryDigest=digest;status="COMPLETED";evidenceReferences=result.evidence().stream().map(EvidenceRef::id).toList();qualityMetadata=Map.of("confidence",result.confidence().name(),"warnings",String.valueOf(result.qualityWarnings().size()),"evidenceCount",String.valueOf(result.evidence().size()));if(ai!=null){aiProvider=ai.provider();aiModel=ai.model();aiOutcome=ai.outcome();aiLatencyMs=ai.latencyMs();}}
 public UUID getId(){return id;}public UUID getOwnerUserId(){return ownerUserId;}public UUID getProjectId(){return projectId;}public UUID getEnvironmentId(){return environmentId;}public Instant getCreatedAt(){return createdAt;}public Instant getFromTime(){return fromTime;}public Instant getToTime(){return toTime;}public String getQueryKind(){return queryKind;}public String getStatus(){return status;}public List<String> getEvidenceReferences(){return evidenceReferences;}public Map<String,String> getQualityMetadata(){return qualityMetadata;}public String getAiProvider(){return aiProvider;}public String getAiModel(){return aiModel;}public String getAiOutcome(){return aiOutcome;}public Long getAiLatencyMs(){return aiLatencyMs;}
}

